import com.opentasker.ui.theme.OpenTaskerTheme
import java.util.Base64

/**
 * The Watch D3's after-walk pages, from the REAL bytes of its first walk (2026-10-18, 2.00 km,
 * 37:02) — to be held against 白い熊's photos of the watch's own screens.
 *
 * **`@PreviewTest` is not optional** — the engine discovers that annotation, not `@Preview`.
 */
private const val SUMMARY = ""
private val SAMPLES = listOf(
    "",
    "",
    "",
    "",
    "",
    "AgIAAQMCAAUEDgABAAVq1J/zBQAOCAAnCAIAAAkEAAAAAAVwbQAGCQAACrBtAAAJAAAKr28ACgoAAAqucQAJCAAACq5yAAAIAAAKr3EACQgAAAqvcAAAAAAACq5tAAAAAAAKrW8ABwgAAAqucQAICAAACrFyAAgIAAAKtnMACAgAAArBdQAICAAACs13AAYIAAAK0Q==",
)

private fun tlv(b64: String) = listOf(HuaweiProtocol.Tlv(0x81, Base64.getDecoder().decode(b64)))
private val SUMM = HuaweiWorkout.parseSummary(tlv(SUMMARY))!!
private val BLOCKS = SAMPLES.mapNotNull { HuaweiWorkout.parseSamples(tlv(it)) }

private val WALK = HuaweiWorkoutStore.Workout(
    startSeconds = 1_792_317_320L, number = 1, endSeconds = 1_792_319_543L, sportType = 2, kind = "walk",
    distanceMetres = 2000, steps = 3174, calories = 156, elevationGainDm = 367, meanSpeedDmS = 8,
    intervalSeconds = 5, sampleCount = 444, trackPoints = 2219, recovery = SUMM.recovery,
)
private val EFFORT = HuaweiWorkoutStore.Effort(
    intervalSeconds = 5,
    heart = BLOCKS.flatMap { it.heart },
    speedDmS = BLOCKS.flatMap { it.speedDmS },
    stepsPerInterval = BLOCKS.flatMap { it.steps },
    recovery = SUMM.recovery,
    altitudeDm = BLOCKS.flatMap { it.altitudeDm },
    summary = SUMM,
)

@Composable
private fun Frame(lang: BandLanguage) {
    OpenTaskerTheme {
        Surface(Modifier.fillMaxSize(), color = MaterialTheme.colorScheme.background) {
            CompositionLocalProvider(LocalBandLanguage provides lang) {
                Column(Modifier.padding(10.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
                    EffortCard(WALK, EFFORT)
                    WalkMetricsCards(WALK, EFFORT)
                }
            }
        }
    }
}

@PreviewTest
@Preview(name = "D3 walk — English", widthDp = 413, heightDp = 1900, showBackground = true)
@Composable
fun D3WalkEnglish() = Frame(BandLanguage.EN)

@PreviewTest
@Preview(name = "D3 walk — 日本語", widthDp = 413, heightDp = 1900, showBackground = true)
@Composable
fun D3WalkJapanese() = Frame(BandLanguage.JA)
